"""Use generated byte patterns, not SyntheticSource, as the recording oracle."""

from pathlib import Path
from tempfile import TemporaryDirectory

import pytest
from hypothesis import given, settings
from hypothesis import strategies as st

from recoryn.domain import AudioFormat, PCMBlock
from recoryn.storage import ChunkWriter, Library, verify_bundle

pytestmark = pytest.mark.property


@settings(max_examples=30, deadline=None, derandomize=True, database=None)
@given(
    sample_rate=st.sampled_from((16000, 44100, 48000)),
    channels=st.integers(1, 2),
    sample_type=st.sampled_from(("s16le", "s24le", "s32le", "f32le")),
    frame_counts=st.lists(st.integers(1, 31), min_size=1, max_size=10),
)
def test_original_pcm_is_exact_concatenation(
    sample_rate: int, channels: int, sample_type: str, frame_counts: list[int]
) -> None:
    sample_bytes = {"s16le": 2, "s24le": 3, "s32le": 4, "f32le": 4}[sample_type]
    frame_bytes = channels * sample_bytes
    audio_format = AudioFormat(sample_rate, channels, sample_type)
    assert audio_format.frame_bytes == frame_bytes
    blocks: list[PCMBlock] = []
    offset = 0
    for sequence, frames in enumerate(frame_counts):
        payload = bytes((offset + index) % 251 for index in range(frames * frame_bytes))
        blocks.append(
            PCMBlock(
                session_id="original",
                track_id="system",
                epoch_id="epoch1",
                sequence=sequence,
                format=audio_format,
                frame_count=frames,
                payload=payload,
                capture_mono_ns=offset // frame_bytes * 1_000_000_000 // sample_rate,
                arrival_mono_ns=offset // frame_bytes * 1_000_000_000 // sample_rate,
                device_frame_position=offset // frame_bytes,
            )
        )
        offset += len(payload)
    expected = b"".join(block.payload for block in blocks)
    with TemporaryDirectory(prefix="recoryn-qa-property-") as directory:
        root = Path(directory)
        with Library(root) as library:
            library.create_session("original")
            writer = ChunkWriter(root, blocks[0], chunk_id="known")
            for block in blocks:
                writer.append(block)
            descriptor = writer.seal()
            library.register_chunk(descriptor)
            bundle = root / descriptor.relative_path
            assert (bundle / "audio.pcm").read_bytes() == expected
            assert descriptor.frame_count == sum(frame_counts)
            assert descriptor.byte_count == len(expected)
            assert verify_bundle(bundle).to_dict() == descriptor.to_dict()
            before = {path: path.read_bytes() for path in bundle.iterdir() if path.is_file()}
            library.recover_session("original")
            library.recover_session("original")
            assert sum(chunk.frame_count for chunk in library.chunks("original")) == sum(
                frame_counts
            )
            assert all(path.read_bytes() == content for path, content in before.items())
